// This is the input string you would get from your JSON object
const chatInput = {{ $json.task_name }};

// Step 1: Split the string into an array of words
// The `split(' ')` method breaks the string at each space.
const words = chatInput.split(' ');
// The `words` array now looks like: ["debit", "cash", "yyy", "zzz", "1000"]

// Step 2: Get the first word
// Arrays are zero-indexed, so the first element is at index 0.
const firstWord = words[0];

// Step 3: Get the last word (the amount)
// The last element is at the index `array.length - 1`.
const lastWord = words[words.length - 1];

// Step 4: Get all the words in between as a single string
// `slice(1, words.length - 1)` extracts a new array from index 1
// up to (but not including) the last element.
// `join(' ')` then merges these words back into a single string with spaces.
const middleWords = words.slice(1, words.length - 1).join(' ');


