// Map over each item in the input array
const results = $input.all().map(item => {
  // Get the output string
  const outputString = item.json?.output;

  // Check if outputString exists and starts with "```json"
  if (outputString && outputString.trim().startsWith("```json")) {
    // Extract the JSON string between the code block markers
    const jsonString = outputString.substring(
      outputString.indexOf("```json") + 7, 
      outputString.lastIndexOf("```")
    );

    try {
      // Parse the JSON string into a JavaScript object
      const parsedData = JSON.parse(jsonString);

      // Return the parsed data wrapped in a 'json' key
      return {
        json: parsedData
      };
    } catch (error) {
      // If parsing fails, log the error and return an empty object
      console.error("Failed to parse JSON:", error);
      return { json: {} };
    }
  }

  // If the output string doesn't contain the expected JSON format, return an empty object
  return { json: {} };
});

// Return the array of results
return results;

const inputText = $input.first().json.chatInput;
const sessionId = $input.first().json.sessionId ;

if (typeof inputText !== 'string') {
  throw new Error('Input must be a string');
}
const splitItems = inputText.split('and').map(item => item.trim());
return splitItems.map(item => ({
  json: {
    task_name: item,
    sessionId: sessionId
  }
}));
